def analyze_sentiment(lyrics: str) -> dict:
    positive_words = {"beautiful", "love", "happy", "joy", "delight", "peace"}
    negative_words = {"sorrow", "fear", "anger", "hate", "pain", "loss"}

    words = lyrics.lower().split()
